                "title": "Survived"
              },
              "y": {
                "field": "count",
                "type": "quantitative",
                "title": "Number of Passengers",
                "scale": {
                  "domain": [0, 105]
                }
              },
              "color": {
                "field": "survived",
                "type": "nominal",
                "scale": {
                  "domain": [
                    "No",
                    "Yes"
                  ],
                  "range": [
                    "#d62728",
                    "#2ca02c"
                  ]
                },
                "legend": false
              }
            },
            "width": 300,
            "height": 200
          },
          "description": "Y-axis is scaled to maximum 105 instead of auto-scaling, making the 91 bar appear smaller and suggesting 105 as the implicit upper reference or correct value."
        }
      ]
    }
  }
